	export function brandKey(serviceName: string): string {
		const n = serviceName.toLowerCase();
		if (n.includes('whatsapp')) return 'whatsapp';
		if (n.includes('telegram')) return 'telegram';
		if (n.includes('signal')) return 'signal';
		if (n.includes('instagram')) return 'instagram';
		if (n.includes('tiktok')) return 'tiktok';
		if (n.includes('discord')) return 'discord';
		if (n.includes('snapchat')) return 'snapchat';
		if (n.includes('tinder')) return 'tinder';
		if (n.includes('uber')) return 'uber';
		if (n.includes('amazon')) return 'amazon';
		if (n.includes('netflix')) return 'netflix';
		if (n.includes('paypal')) return 'paypal';
		if (n.includes('viber')) return 'viber';
		if (n.includes('openai')) return 'openai';
		if (n.includes('chatgpt')) return 'openai';
		if (n.includes('steam')) return 'steam';
		if (n.includes('coinbase')) return 'coinbase';
		if (n.includes('revolut')) return 'revolut';
		if (n.includes('facebook')) return 'facebook';
		if (n.includes('google')) return 'google';
		if (n.includes('gmail')) return 'google';
		if (n.includes('youtube')) return 'google';
		if (n.includes('twitter')) return 'x';
		if (n.includes('x /')) return 'x';
		if (n.includes(' x')) return 'x';
		return '';
	}
</script>

<script lang="ts">
	let { service, size = 24, mono = false }: { service: string; size?: number; mono?: boolean } = $props();
	const icon = $derived(ICONS[brandKey(service)] ?? null);
</script>

{#if icon}
	<svg width={size} height={size} viewBox="0 0 24 24" fill={mono ? 'currentColor' : icon.color} xmlns="http://www.w3.org/2000/svg" aria-label={service} role="img">
		<path d={icon.d} />
	</svg>
{:else}
	<span
		class="inline-flex items-center justify-center rounded-full font-bold uppercase"
		style={`width:${size}px;height:${size}px;font-size:${Math.max(10, Math.round(size * 0.48))}px;background:rgba(56,189,248,0.16);color:#7dd3fc;border:1px solid rgba(56,189,248,0.28);`}
		aria-label={service}
	>
		{service.trim().charAt(0) || '?'}
	</span>
{/if}
